import {boundsIntersectCollider} from './collision-shapes.js';
import {MATERIALS,LIMITS} from './items.js';
export const GRID=Object.freeze({cell:5,level:3.6,thickness:.22,maxHeight:72});
const snap=n=>Math.round(n/GRID.cell)*GRID.cell;
export const gridAngle=n=>Math.round(n/(Math.PI/2))*(Math.PI/2);
export const gridBaseY=s=>s.y+(Number.isFinite(s.groundOffset)?s.groundOffset:0);
export function rampEndpoints(s){const dx=-Math.sin(s.angle)*2.5,dz=-Math.cos(s.angle)*2.5;return {bottom:[s.x-dx,s.y,s.z-dz],top:[s.x+dx,s.y+GRID.level,s.z+dz]};}
export function rampHeight(s,x,z){const dx=x-s.x,dz=z-s.z,lx=dx*Math.cos(s.angle)-dz*Math.sin(s.angle),lz=dx*Math.sin(s.angle)+dz*Math.cos(s.angle);return Math.abs(lx)<=2.5+1e-6&&Math.abs(lz)<=2.5+1e-6?s.y+(2.5-lz)*GRID.level/GRID.cell:null;}
export function gridPlacement(p,input,world,structures=[]){const baseHeight=(x,z)=>world.supportHeight?world.supportHeight(x,z,p.p[1],.55):world.height(x,z),angle=gridAngle(input.yaw+(input.rotation||0)),dx=-Math.sin(angle),dz=-Math.cos(angle),type=input.slot===10?3:2,material=input.material==='stone'?'stone':'wood';let x=snap(p.p[0]+dx*3),z=snap(p.p[2]+dz*3),y=world.supportHeight&&type===3?baseHeight(x,z):Math.floor(baseHeight(x,z)/GRID.level)*GRID.level,groundOffset=0;if(type===3){const near=structures.filter(s=>s.type===3&&Math.abs(Math.sin(s.angle-angle))<.01&&Math.cos(s.angle-angle)>.9).map(s=>({s,end:rampEndpoints(s).top})).filter(({end})=>Math.hypot(end[0]-p.p[0],end[2]-p.p[2])<3.5&&Math.abs(end[1]-p.p[1])<1.8).sort((a,b)=>Math.hypot(a.end[0]-p.p[0],a.end[2]-p.p[2])-Math.hypot(b.end[0]-p.p[0],b.end[2]-p.p[2]));if(near.length){const end=near[0].end;x=end[0]+dx*2.5;z=end[2]+dz*2.5;y=end[1];}else if(p.p[1]>baseHeight(x,z)+2)y=Math.round(p.p[1]/GRID.level)*GRID.level;}else{x+=dx*2.5;z+=dz*2.5;const rampEdge=structures.filter(s=>s.type===3&&Math.abs(Math.sin(s.angle-angle))<.01).flatMap(s=>{const e=rampEndpoints(s);return [e.bottom,e.top];}).filter(end=>Math.hypot(end[0]-p.p[0],end[2]-p.p[2])<3.65&&Math.abs(end[1]-p.p[1])<2.15).sort((a,b)=>Math.hypot(a[0]-p.p[0],a[2]-p.p[2])-Math.hypot(b[0]-p.p[0],b[2]-p.p[2]))[0],stack=structures.filter(s=>s.type===2&&Math.abs(Math.sin(s.angle-angle))<.01&&Math.abs(gridBaseY(s)+GRID.level-p.p[1])<2.15&&Math.hypot(s.x-x,s.z-z)<2.7).sort((a,b)=>gridBaseY(b)-gridBaseY(a))[0];if(rampEdge){[x,y,z]=rampEdge;}else if(stack){x=stack.x;z=stack.z;y=stack.y+GRID.level;groundOffset=Number.isFinite(stack.groundOffset)?stack.groundOffset:0;}else{const sx=Math.cos(angle)*2.5,sz=-Math.sin(angle)*2.5,maxFloor=Math.max(baseHeight(x,z),baseHeight(x+sx,z+sz),baseHeight(x-sx,z-sz));groundOffset=Math.max(0,Math.min(GRID.level-.01,maxFloor-y));if(p.p[1]>maxFloor+2)y=Math.round(p.p[1]/GRID.level)*GRID.level;}}const result={x,z,y,angle,type,material,hp:MATERIALS[material].hp};if(type===2&&groundOffset>1e-6)result.groundOffset=groundOffset;return result;}
export function gridBounds(s){const rotated=Math.abs(Math.sin(s.angle))>.5,y=gridBaseY(s);return {min:[s.x-(rotated?GRID.thickness/2:2.5),y,s.z-(rotated?2.5:GRID.thickness/2)],max:[s.x+(rotated?GRID.thickness/2:2.5),y+GRID.level,s.z+(rotated?2.5:GRID.thickness/2)]};}
const overlap=(a,b)=>a.min.every((v,i)=>v<b.max[i]&&a.max[i]>b.min[i]);
export function supported(s,structures,world){const base=s.type===3?s.y:gridBaseY(s),bottom=s.type===3?rampEndpoints(s).bottom:[s.x,base,s.z],floor=world.supportHeight?world.supportHeight(bottom[0],bottom[2],base,.55):world.height(bottom[0],bottom[2]);if(base>=floor-GRID.level&&base<=floor+.5)return true;return structures.some(v=>{const top=v.type===3?rampEndpoints(v).top:[v.x,v.y+GRID.level,v.z];return Math.abs(top[1]-s.y)<1e-5&&Math.hypot(top[0]-bottom[0],top[2]-bottom[2])<= (s.type===3?.01:2.51)||Math.abs(v.y-s.y)<1e-5&&Math.hypot(v.x-s.x,v.z-s.z)<=5.01;});}
export function gridValid(s,structures,players,world){if(![s.x,s.y,s.z,s.angle].every(Number.isFinite)||structures.length>=LIMITS.structures||s.y>GRID.maxHeight||![2,3].includes(s.type))return false;if(structures.some(v=>Math.hypot(v.x-s.x,v.z-s.z)<.01&&Math.abs(v.y-s.y)<.01&&v.type===s.type&&(s.type===3?Math.cos(v.angle-s.angle)>.99:Math.abs(Math.sin(v.angle-s.angle))<.01)))return false;const box=s.type===2?gridBounds(s):{min:[s.x-2.48,s.y+.2,s.z-2.48],max:[s.x+2.48,s.y+3.4,s.z+2.48]};if((world.obstacles||[]).some(v=>v.planes?.length?boundsIntersectCollider(box,v):overlap(box,v)))return false;if(s.type===2&&players.some(p=>p.hp>0&&p.air==='landed'&&overlap(box,{min:[p.p[0]-.36,p.p[1]+.1,p.p[2]-.36],max:[p.p[0]+.36,p.p[1]+1.78,p.p[2]+.36]})))return false;return supported(s,structures,world);}
// Intersect the ramp plane, rather than its entire empty bounding volume.
export function rayRamp(origin,direction,s){const c=Math.cos(s.angle),n=Math.sin(s.angle),lz=(origin[0]-s.x)*n+(origin[2]-s.z)*c,dz=direction[0]*n+direction[2]*c,denom=direction[1]+dz*.72;if(Math.abs(denom)<1e-8)return Infinity;const t=(s.y+1.8-lz*.72-origin[1])/denom;if(t<0)return Infinity;return rampHeight(s,origin[0]+direction[0]*t,origin[2]+direction[2]*t)===null?Infinity:t;}
